/* Mozai (墨仔) - standalone writing pet component.
   Self-contained: embedded forms (generated with Agnes AI), state machine,
   idle theater, interactions. Exposes window.Mozai; no path dependencies. */
(function () {
  "use strict";

  var FORMS = {
    idle: "data:image/jpeg;base64,",
    typing: "data:image/jpeg;base64,",
    sleep: "data:image/jpeg;base64,",
    happy: "data:image/jpeg;base64,",
    party: "data:image/jpeg;base64,",
  };
  var FORM_NAMES = {
    idle: ["坐姿墨仔", "Chill Mozai"],
    typing: ["敲键盘墨仔", "Typing Mozai"],
    sleep: ["瞌睡墨仔", "Sleepy Mozai"],
    happy: ["开心墨仔", "Happy Mozai"],
    party: ["派对墨仔", "Party Mozai"],
  };
  var QUOTES = {
    "zh-CN": [
      "写作是把噪音调成静音。",
      "先写烂，再改好。",
      "删掉一半，文章就活了。",
      "段落是呼吸，留白是标点。",
      "公众号读者三秒定去留，第一句要值三秒。",
      "别删那个开头，你只是还没写到它该在的地方。",
      "我是墨仔，码聋的猫。听不见吵闹，只听得见键盘。",
    ],
    en: [
      "Writing is tuning noise into silence.",
      "Write it bad first, then make it good.",
      "Cut half, and the piece comes alive.",
      "Paragraphs breathe; whitespace punctuates.",
      "Readers decide in three seconds - earn them.",
      "I am Mozai, the code-deaf cat. I only hear keyboards.",
    ],
  };

  var base = "idle";
  var currentForm = "";
  var formIdx = 0;
  var busy = false;
  var lang = function () {
    try { return localStorage.getItem("wxwright-lang") || "zh-CN"; } catch (e) { return "zh-CN"; }
  };

  function $(id) { return document.getElementById(id); }
  function el() { return $("pet"); }
  function img() { return $("pet-img"); }

  function setForm(form) {
    var im = img();
    if (!im || !FORMS[form] || currentForm === form) return;
    currentForm = form;
    im.classList.remove("pet-swap");
    void im.offsetWidth;
    im.src = FORMS[form];
    im.classList.add("pet-swap");
  }

  function state(s, opts) {
    opts = opts || {};
    var node = el();
    if (!node) return;
    node.className = "";
    node.classList.add("state-" + s);
    var zz = node.querySelector(".pet-zz");
    if (zz) zz.hidden = true;
    if (opts.base !== false) base = s;
    setForm(s);
  }

  function wake() {
    clearTimeout(window.__petSleepTimer);
    window.__petSleepTimer = setTimeout(function () {
      state("sleep");
      var zz = el() && el().querySelector(".pet-zz");
      if (zz) zz.hidden = false;
    }, 45000);
  }

  function hearts() {
    var host = el();
    if (!host) return;
    for (var i = 0; i < 3; i++) {
      (function (i) {
        var h = document.createElement("div");
        h.className = "heart";
        h.style.setProperty("--hx", (Math.random() * 26 - 8).toFixed(0) + "px");
        h.style.animationDelay = i * 0.12 + "s";
        h.innerHTML = '<svg viewBox="0 0 24 24" width="12" height="12"><path fill="currentColor" d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z"/></svg>';
        host.appendChild(h);
        setTimeout(function () { h.remove(); }, 1200);
      })(i);
    }
  }

  function speak(text) {
    var b = $("pet-bubble");
    if (!b) return;
    b.textContent = text;
    b.hidden = false;
    clearTimeout(b._t);
    b._t = setTimeout(function () { b.hidden = true; }, 4200);
  }

  function cycleForm() {
    var keys = Object.keys(FORMS);
    formIdx = (formIdx + 1) % keys.length;
    var k = keys[formIdx];
    state(k);
    wake();
    clearTimeout(window.__petTimer);
    window.__petTimer = setTimeout(function () { state("idle"); }, 6000);
    var names = FORM_NAMES[k];
    speak((lang() === "zh-CN" ? names[0] : names[1]) + (lang() === "zh-CN" ? " 已就位" : " reporting in"));
  }

  function theater() {
    setInterval(function () {
      if (document.hidden || busy || base !== "idle") return;
      var show = ["typing", "happy", "party"][Math.floor(Math.random() * 3)];
      state(show, { base: false });
      setTimeout(function () {
        if (base === "idle") state("idle", { base: false });
      }, 2400);
    }, 13000);
  }

  function bind() {
    var host = el();
    if (!host || host.dataset.bound === "1") return;
    host.dataset.bound = "1";
    host.addEventListener("click", function () {
      hearts();
      wake();
      if (host.className.indexOf("state-sleep") === -1) {
        state("happy");
        clearTimeout(window.__petTimer);
        window.__petTimer = setTimeout(function () { state("idle"); }, 2000);
      }
      var list = QUOTES[lang()] || QUOTES["zh-CN"];
      speak(list[Math.floor(Math.random() * list.length)]);
    });
    host.addEventListener("dblclick", cycleForm);
  }

  window.Mozai = {
    setState: function (s) { state(s); },
    typing: function () {
      state("typing");
      clearTimeout(window.__petTimer);
      window.__petTimer = setTimeout(function () { state("idle"); }, 1100);
      wake();
    },
    celebrate: function () {
      state("happy");
      clearTimeout(window.__petTimer);
      window.__petTimer = setTimeout(function () { state("idle"); }, 2000);
      wake();
    },
    wake: wake,
    setBusy: function (b) { busy = b; },
    formsLoaded: function () { return Object.keys(FORMS).length; },
  };

  function boot() {
    bind();
    state("idle");
    wake();
    theater();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();
